  if id == "" {
      validatedID, err := generateUUID()
      if err != nil { return "", NewErrInternal("could not generate id: %v", err) }
      return validatedID, err
  }
  // IDs are always returned lowercase ... validatedID := strfmt.UUID(strings.ToLower(id.String()))

add.go:206-211 validateUUID:
  func (m *Manager) validateUUID(obj *models.Object) error {
      _, err := uuid.Parse(obj.ID.String())
      return err
  }
  // 空串在 checkIDOrAssignNew 中先被替换为新生成 UUID，validateUUID 之后 parse 的已是合法 UUID——空串路径 by-design 分配随机 id（静默、无告警）。int-null 接受源于 properties_validation.go 对 nil 值跳过类型检查（其余 '12'/1.5/true/[]/{} 均报 invalid integer property）。
